import type {JobRecovery} from './jobRecovery.ts';

const loopback = 'http://127.0.0.1:8787';
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const keyPattern = /^[!-~]{1,900}:p[a-z0-9]{1,99}$/;

export function receiptIdentity(session: unknown, key: unknown) {
  if (typeof session !== 'string' || !uuid.test(session) || typeof key !== 'string' || !keyPattern.test(key)) return;
  return {session,key};
}

// Only a persisted ambiguous web submission can be reconciled. No new key,
// session, POST or native pilot credential may be generated by this path.
export function receiptLookupHeaders(job: JobRecovery | undefined, origin: string, projectId: string, requestId?: string): Record<string,string> | undefined {
  if (origin !== loopback || job?.origin !== origin || job.state !== 'submitting' || !requestId) return;
  let key: string;
  try { key = encodeURIComponent(projectId)+':'+requestId; } catch { return; }
  const identity = receiptIdentity(job.session,key);
  if (identity) return {'X-Forgia-Session':identity.session,'Idempotency-Key':identity.key};
}
